import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  describe("quote — base premiums", () => {
    it.todo("empty item list → premium 5 G (only the processing fee)");
    it.todo("a single sword → base premium 100 G");
    it.todo("a single amulet → base premium 60 G");
    it.todo("a single staff → base premium 80 G");
    it.todo("a single potion → base premium 40 G");
    it.todo("a single rune (component) → base premium 25 G");
    it.todo("a single moonstone (component) → base premium 25 G");
  });

  describe("quote — building block of 3 alike components", () => {
    it.todo("2 runes → 50 G base premium");
    it.todo("3 runes → 60 G base premium (block applies)");
    it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
    it.todo("7 runes → 175 G base premium");
    it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
    it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
  });

  describe("quote — item-specific modifiers", () => {
    it.todo("cursed sword adds 50 % risk surcharge → 50 G on top of 100 G base");
    it.todo("sword with enchantment 5 → high-enchantment surcharge applies (30 G)");
    it.todo("sword with enchantment 4 → no high-enchantment surcharge");
    it.todo("cursed sword with enchantment 5 → both surcharges apply");
    it.todo("cursed sword with enchantment 4 → only the curse surcharge applies");
  });

  describe("quote — policy-wide modifiers", () => {
    it.todo("customer with exactly 2 years with MHPCO → 20 % loyalty discount applies");
    it.todo("customer with 1 year with MHPCO → no loyalty discount");
    it.todo("first quote in a scenario → 10 % initial assessment surcharge on the policy base premium");
    it.todo("second quote in a scenario → 15 % follow-up contract discount");
    it.todo("the first insurance surcharge still applies on a follow-up contract");
  });

  describe("quote — modifier scope on multi-item policies", () => {
    it.todo(
      "cursed sword (100 G) + plain amulet (60 G) → policy base 160 G; curse adds 50 G (50 % of the cursed item only) → 210 G before further modifiers and fee",
    );
    it.todo("policy-wide modifiers apply to the sum of all item base premiums, the fee is added at the very end");
  });

  describe("quote — processing fee and rounding", () => {
    it.todo("a 5 G processing fee is added to every premium");
    it.todo("a premium calculation that yields 197.5 G → final premium 198 G (rounded up)");
    it.todo("intermediate amounts are kept as fractions; only the final premium is rounded");
  });

  describe("quote — integration examples", () => {
    it.todo("newcomer (0 years, no previous contract) with a cursed sword (steel, enchantment 3) → premium 165 G");
    it.todo("long-standing customer (3 years), second quote, cursed sword (steel, enchantment 7) → premium 160 G");
  });

  describe("claim — standard reimbursement", () => {
    it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
    it.todo("damage to a rune (insurance value 250 G), damage 200 G → payout 100 G (no enchantment or material)");
  });

  describe("claim — special clauses", () => {
    it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full reimbursement, then deductible)");
    it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % first, then deductible)");
    it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (the 50 % rule wins, then deductible)");
    it.todo("dragon-material sword with exactly enchantment 8, damage 1000 G → payout 400 G");
  });

  describe("claim — deductible per damage event", () => {
    it.todo("dragon attack damages a sword (500 G) and an amulet (300 G) → payout 600 G (deductible once per damaged item)");
  });

  describe("claim — insurance sum and cap", () => {
    it.todo("a policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
    it.todo("a policy covering a cursed sword → cap 2000 G (premium modifiers do not raise the cap)");
    it.todo("a policy covering a sword and 3 runes (a block) → insurance sum 1750 G, cap 3500 G (block discount affects the premium only)");
    it.todo("a policy covering two swords → insurance sum 2000 G, cap 4000 G");
  });

  describe("claim — cap exhaustion across successive claims", () => {
    it.todo("sword (cap 2000 G), first claim of 1500 G → payout 1400 G, remainingCap 600 G");
    it.todo("sword (cap 2000 G), second claim of 1500 G → payout 600 G, remainingCap 0 G");
  });

  describe("claim — multiple items of the same type", () => {
    it.todo("two insured swords, two sword damage entries → each entry is a separate damage with its own deductible");
    it.todo("more damage entries of a type than the policy covers → error (non-zero exit)");
  });

  describe("claim — rounding", () => {
    it.todo("a payout calculation that yields 350.5 G → final payout 350 G (rounded down)");
  });

  describe("errors", () => {
    it.todo("quote with an item of unknown type (e.g. broomstick) → error, no results");
    it.todo("claim referencing a damage entry whose item is not part of the policy → error");
    it.todo("claim referencing a damage entry with an unknown item type → error");
    it.todo("claim with a damage entry of amount -200 → error");
  });

  describe("CLI", () => {
    it.todo("reads a scenario from stdin and writes {results: [...]} to stdout");
    it.todo("returns one result per step, in order (quote → premium, claim → payout and remainingCap)");
    it.todo("exits with a non-zero status code and writes an error description to stderr on invalid input");
  });
});

