export interface Item {
  type: string;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: QuoteStep[];
}

export interface ScenarioOutput {
  results: unknown[];
}

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE = 0.1;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
};

export const runScenario = (scenario: Scenario): ScenarioOutput => {
  return {
    results: scenario.steps.map((step) => {
      const base = step.items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
      return { premium: base + base * FIRST_INSURANCE_SURCHARGE + PROCESSING_FEE };
    }),
  };
};

