export interface Item {
  type: string;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: QuoteStep[];
}

export interface ScenarioOutput {
  results: unknown[];
}

const PROCESSING_FEE = 5;
const INITIAL_ASSESSMENT_SURCHARGE_RATE = 0.1;

const BASE_PREMIUMS: Record<string, number | undefined> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type] ?? 0;

const COMPONENT_TYPES = new Set(["rune"]);
const COMPONENT_BLOCK_SIZE = 3;
const COMPONENT_BLOCK_PREMIUM = 60;

const isComponent = (item: Item): boolean => COMPONENT_TYPES.has(item.type);

/** A "building block": exactly 3 components, all of the same type. */
const formsComponentBlock = (items: Item[]): boolean =>
  items.length === COMPONENT_BLOCK_SIZE &&
  items.every((item) => isComponent(item) && item.type === items[0].type);

const sumOfItemBasePremiums = (items: Item[]): number =>
  items.reduce((sum, item) => sum + basePremiumOf(item), 0);

const policyBasePremiumOf = (step: QuoteStep): number =>
  formsComponentBlock(step.items) ? COMPONENT_BLOCK_PREMIUM : sumOfItemBasePremiums(step.items);

/** Kept as an exact fraction — only the final premium is rounded. */
const premiumBeforeRounding = (step: QuoteStep): number => {
  const policyBasePremium = policyBasePremiumOf(step);
  const initialAssessmentSurcharge = policyBasePremium * INITIAL_ASSESSMENT_SURCHARGE_RATE;
  return policyBasePremium + initialAssessmentSurcharge + PROCESSING_FEE;
};

/** Rounded up, in the MHPCO's favour. */
const finalPremiumFor = (step: QuoteStep): number => Math.ceil(premiumBeforeRounding(step));

export const runScenario = (scenario: Scenario): ScenarioOutput => ({
  results: scenario.steps.map((step) => ({ premium: finalPremiumFor(step) })),
});

export interface Item {
  type: string;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: QuoteStep[];
}

export interface ScenarioOutput {
  results: unknown[];
}

const PROCESSING_FEE = 5;
const INITIAL_ASSESSMENT_SURCHARGE_RATE = 0.1;

const BASE_PREMIUMS: Record<string, number | undefined> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type] ?? 0;

const COMPONENT_TYPES = new Set(["rune"]);
const COMPONENT_BLOCK_SIZE = 3;
const COMPONENT_BLOCK_PREMIUM = 60;

const isComponent = (item: Item): boolean => COMPONENT_TYPES.has(item.type);

const countByType = (items: Item[]): Map<string, number> => {
  const counts = new Map<string, number>();
  for (const item of items) {
    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  }
  return counts;
};

/**
 * Components of one type form a "building block" only when there are exactly 3
 * of them; otherwise each is priced individually.
 */
const componentGroupPremium = (type: string, count: number): number =>
  count === COMPONENT_BLOCK_SIZE ? COMPONENT_BLOCK_PREMIUM : count * (BASE_PREMIUMS[type] ?? 0);

const policyBasePremiumOf = (step: QuoteStep): number => {
  const components = step.items.filter(isComponent);
  const mainItems = step.items.filter((item) => !isComponent(item));

  let total = mainItems.reduce((sum, item) => sum + basePremiumOf(item), 0);
  for (const [type, count] of countByType(components)) {
    total += componentGroupPremium(type, count);
  }
  return total;
};

/** Kept as an exact fraction — only the final premium is rounded. */
const premiumBeforeRounding = (step: QuoteStep): number => {
  const policyBasePremium = policyBasePremiumOf(step);
  const initialAssessmentSurcharge = policyBasePremium * INITIAL_ASSESSMENT_SURCHARGE_RATE;
  return policyBasePremium + initialAssessmentSurcharge + PROCESSING_FEE;
};

/** Rounded up, in the MHPCO's favour. */
const finalPremiumFor = (step: QuoteStep): number => Math.ceil(premiumBeforeRounding(step));

export const runScenario = (scenario: Scenario): ScenarioOutput => ({
  results: scenario.steps.map((step) => ({ premium: finalPremiumFor(step) })),
