export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Customer {
  yearsWithMHPCO: number;
}

export interface Scenario {
  customer: Customer;
  steps: QuoteStep[];
}

export interface ScenarioOutput {
  results: unknown[];
}

const PROCESSING_FEE = 5;
const INITIAL_ASSESSMENT_SURCHARGE_RATE = 0.1;
const LOYALTY_YEARS = 2;
const LOYALTY_DISCOUNT_RATE = 0.2;
const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;

const BASE_PREMIUMS: Record<string, number | undefined> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const basePremiumOfType = (type: string): number => BASE_PREMIUMS[type] ?? 0;

const CURSE_SURCHARGE_RATE = 0.5;
const HIGH_ENCHANTMENT_LEVEL = 5;
const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;

const isCursed = (item: Item): boolean => item.cursed === true;
const isHighlyEnchanted = (item: Item): boolean =>
  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;

/** Item-specific modifiers apply to the base premium of the affected item only. */
const itemSurchargesOf = (item: Item): number => {
  const basePremium = basePremiumOfType(item.type);
  const curseSurcharge = isCursed(item) ? basePremium * CURSE_SURCHARGE_RATE : 0;
  const highEnchantmentSurcharge = isHighlyEnchanted(item)
    ? basePremium * HIGH_ENCHANTMENT_SURCHARGE_RATE
    : 0;
  return curseSurcharge + highEnchantmentSurcharge;
};

const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
const COMPONENT_BLOCK_SIZE = 3;
const COMPONENT_BLOCK_PREMIUM = 60;

const isComponent = (type: string): boolean => COMPONENT_TYPES.has(type);

const countByType = (items: Item[]): Map<string, number> => {
  const counts = new Map<string, number>();
  for (const item of items) {
    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  }
  return counts;
};

/**
 * Items of one type are normally priced individually. The exception is
 * components: exactly 3 alike ones form a "building block" priced as a unit.
 */
const typeGroupPremium = (type: string, count: number): number =>
  isComponent(type) && count === COMPONENT_BLOCK_SIZE
    ? COMPONENT_BLOCK_PREMIUM
    : count * basePremiumOfType(type);

const policyBasePremiumOf = (step: QuoteStep): number =>
  [...countByType(step.items)].reduce(
    (sum, [type, count]) => sum + typeGroupPremium(type, count),
    0,
  );

const isLongStanding = (customer: Customer): boolean =>
  customer.yearsWithMHPCO >= LOYALTY_YEARS;

/**
 * Policy-wide modifiers are signed rates charged against the policy base
 * premium: surcharges positive, discounts negative.
 */
const policyModifierRateFor = (customer: Customer, isFollowUpContract: boolean): number =>
  INITIAL_ASSESSMENT_SURCHARGE_RATE -
  (isLongStanding(customer) ? LOYALTY_DISCOUNT_RATE : 0) -
  (isFollowUpContract ? FOLLOW_UP_CONTRACT_DISCOUNT_RATE : 0);

const itemSurchargesOfPolicy = (step: QuoteStep): number =>
  step.items.reduce((sum, item) => sum + itemSurchargesOf(item), 0);

/** Kept as an exact fraction — only the final premium is rounded. */
const premiumBeforeRounding = (step: QuoteStep, customer: Customer): number => {
  const policyBasePremium = policyBasePremiumOf(step);
  const policyModifiers = policyBasePremium * policyModifierRateFor(customer);
  return policyBasePremium + itemSurchargesOfPolicy(step) + policyModifiers + PROCESSING_FEE;
};

/** Rounded up, in the MHPCO's favour. */
const finalPremiumFor = (step: QuoteStep, customer: Customer): number =>
  Math.ceil(premiumBeforeRounding(step, customer));

export const runScenario = (scenario: Scenario): ScenarioOutput => ({
  results: scenario.steps.map((step) => ({ premium: finalPremiumFor(step, scenario.customer) })),
});

