  moonstone: 250,
};

const DEDUCTIBLE = 100;
const CAP_MULTIPLIER = 2;

const insuranceSumOf = (step: QuoteStep): number =>
  step.items.reduce((sum, item) => sum + (INSURANCE_VALUES[item.type] ?? 0), 0);

