const settleClaim = (step: ClaimStep, policy: Policy): { payout: number; remainingCap: number } => {
  const desired = step.incident.damages.reduce((sum, damage) => sum + payoutForDamage(damage), 0);
  const payout = Math.floor(Math.min(desired, policy.remainingCap));

  policy.remainingCap -= payout;
  return { payout, remainingCap: policy.remainingCap };
};

